import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import type { BuildingEntity } from '../Entity/BuildingEntity';
import { GRID_COLS, GRID_ROWS } from '../Config/GridConfig';
import { HallEvents } from '../HallEvents';

// 定义查询接口，切断直接依赖
export interface IGridQuery {
    isOccupied(x: number, y: number): boolean;
    getAt(x: number, y: number): BuildingEntity | null;
}

export class GridSystem implements System, IGridQuery {
    // 核心：使用二维数组，空位用 null 表示
    // 注意：数组是 _grid[row][col]，即 _grid[y][x]
    private _grid: (BuildingEntity | null)[][] = [];
    private _world: World = null!;

    onStart(world: World): void {
        this._world = world;
        this._initGrid();

        // 事件驱动：监听建/拆，更新数组
        world.bus.on(HallEvents.BUILD_COMPLETED, this._onBuildCompleted, this);
        world.bus.on(HallEvents.BUILD_REMOVED, this._onBuildRemoved, this);
    }

    onDestroy(world: World): void {
        world.bus.off(HallEvents.BUILD_COMPLETED, this._onBuildCompleted, this);
        world.bus.off(HallEvents.BUILD_REMOVED, this._onBuildRemoved, this);
        this._world = null!;
    }

    onTick(): void {}

    // 初始化固定大小的空地图
    private _initGrid(): void {
        this._grid = [];
        for (let y = 0; y < GRID_ROWS; y++) {
            const row: (BuildingEntity | null)[] = new Array(GRID_COLS).fill(null);
            this._grid.push(row);
        }
    }

    // ===== 提供给外部的 O(1) 查询 =====

    public isOccupied(x: number, y: number): boolean {
        if (x < 0 || x >= GRID_COLS || y < 0 || y >= GRID_ROWS) return true; // 越界视为占用，防止建到外面
        return this._grid[y][x] !== null;
    }

    public getAt(x: number, y: number): BuildingEntity | null {
        if (x < 0 || x >= GRID_COLS || y < 0 || y >= GRID_ROWS) return null;
        return this._grid[y][x];
    }

    // ===== 事件响应 =====

    private _onBuildCompleted(building: BuildingEntity): void {
        // 将实体放入数组
        if (building.gridX >= 0 && building.gridX < GRID_COLS &&
            building.gridY >= 0 && building.gridY < GRID_ROWS) {
            this._grid[building.gridY][building.gridX] = building;
        }
    }

    private _onBuildRemoved(building: BuildingEntity): void {
        // 从数组中移除
        if (building.gridX >= 0 && building.gridX < GRID_COLS &&
            building.gridY >= 0 && building.gridY < GRID_ROWS) {
            this._grid[building.gridY][building.gridX] = null;
        }
    }
}